import{_ as d,C as a,o as i,c,j as e,a as t,E as s,w as l,a6 as h}from"./chunks/framework.DIp0zHSV.js";const A=JSON.parse('{"title":"Check Your Config","description":"Paste LCARdS YAML (a card, a view or a whole dashboard) and see every unknown option, misspelt name and invalid value, with its line and a link to the docs. Runs in your browser.","frontmatter":{"description":"Paste LCARdS YAML (a card, a view or a whole dashboard) and see every unknown option, misspelt name and invalid value, with its line and a link to the docs. Runs in your browser."},"headers":[],"relativePath":"getting-started/config-checker.md","filePath":"getting-started/config-checker.md","lastUpdated":1794365828000}'),u={name:"getting-started/config-checker.md"};function g(m,o,w,p,f,k){const n=a("ConfigChecker",!0),r=a("ClientOnly");return i(),c("div",null,[o[0]||(o[0]=e("h1",{id:"check-your-config",tabindex:"-1"},[t("Check Your Config "),e("a",{class:"header-anchor",href:"#check-your-config","aria-label":'Permalink to "Check Your Config"'},"​")],-1)),o[1]||(o[1]=e("p",null,[e("strong",null,"Paste your YAML below to find what LCARdS won't understand: options that don't exist, misspelt names and values of the wrong kind."),t(" A config LCARdS doesn't understand is mostly ignored without a word, so a typo often looks like a bug.")],-1)),o[2]||(o[2]=e("ul",null,[e("li",null,[e("strong",null,"Works with"),t(" one card, a view, or a whole dashboard: it finds every LCARdS card in it, at any depth.")]),e("li",null,[e("strong",null,"Private:"),t(" this page runs in your browser, and nothing is sent anywhere.")])],-1)),s(r,null,{default:l(()=>[s(n)]),_:1}),o[3]||(o[3]=h('<h2 id="where-to-get-your-yaml" tabindex="-1">Where to get your YAML <a class="header-anchor" href="#where-to-get-your-yaml" aria-label="Permalink to &quot;Where to get your YAML&quot;">​</a></h2><p><strong>Copy it from a card&#39;s code editor or from the dashboard&#39;s raw configuration.</strong></p><ul><li><strong>One card:</strong> open the card editor and switch to its <strong>YAML</strong> tab, then copy everything.</li><li><strong>A whole dashboard:</strong> <strong>Edit dashboard &gt; ⋮ &gt; Raw configuration editor</strong>, then copy everything.</li></ul><h2 id="reading-the-results" tabindex="-1">Reading the results <a class="header-anchor" href="#reading-the-results" aria-label="Permalink to &quot;Reading the results&quot;">​</a></h2><p><strong>Errors are things LCARdS rejects or ignores; warnings are names it doesn&#39;t know and other likely mistakes.</strong> Each result shows the option&#39;s path and line, and links to the docs for that option.</p><ul><li><strong>Errors:</strong> invalid values, keys LCARdS doesn&#39;t have, an MSD with nothing to draw on. Fix these.</li><li><strong>Warnings:</strong> a preset, animation, sound or theme token LCARdS doesn&#39;t have, or a misspelt <code>var(--lcars-*)</code> or <code>var(--lcards-*)</code> colour, almost always a typo; the checker suggests the closest match. A name from a content pack of your own also shows as a warning, and is fine.</li><li>A warning about an older chart or data grid format means the config still works but can be updated.</li><li><strong>Missing animation params:</strong> some animation presets do nothing without certain params, such as <code>color-shift</code> without <code>color_from</code> and <code>color_to</code>; the warning names the ones to add.</li><li><strong>Cut-off values:</strong> in YAML a <code>#</code> after a space starts a comment, so an unquoted <code>color: var(--lcars-alert-red, #cc0000)</code> reads as <code>var(--lcars-alert-red,</code>. A value that ends in a comma, or opens a CSS function it never closes, warns: put the whole value in quotes.</li></ul><h2 id="pasting-into-home-assistant-s-code-editor" tabindex="-1">Pasting into Home Assistant&#39;s code editor <a class="header-anchor" href="#pasting-into-home-assistant-s-code-editor" aria-label="Permalink to &quot;Pasting into Home Assistant&#39;s code editor&quot;">​</a></h2><p><strong>Home Assistant&#39;s own code editor reads a few unquoted words as <code>true</code> or <code>false</code>, so quote them there.</strong> That is the editor in a card dialog&#39;s <strong>Show code editor</strong> and the raw configuration editor.</p><ul><li><code>y</code>, <code>yes</code> and <code>on</code> become <code>true</code>, and <code>n</code>, <code>no</code> and <code>off</code> become <code>false</code>, in any case. So <code>y: 20</code> arrives as <code>true: 20</code>, and <code>label: N</code> as <code>label: false</code>.</li><li>Quote them: <code>&quot;y&quot;: 20</code>, <code>label: &quot;N&quot;</code>. The checker warns about each one (<strong>Home Assistant&#39;s code editor reads...</strong>).</li><li>The LCARdS editor&#39;s own <strong>YAML</strong> tab reads them as written.</li></ul><h2 id="other-ways-to-check" tabindex="-1">Other ways to check <a class="header-anchor" href="#other-ways-to-check" aria-label="Permalink to &quot;Other ways to check&quot;">​</a></h2><p><strong>The same checker runs in Claude, on the command line and in the card editors.</strong></p><ul><li><strong>Ask Claude:</strong> with the <a href="./ai-assistance.html#with-claude-easiest">LCARdS skill</a> loaded, paste your YAML and ask <em>&quot;check this LCARdS config and fix it&quot;</em>. Claude runs this same checker, explains each problem and gives you the corrected YAML.</li><li><strong>Command line:</strong> download <a href="/dev/tools/lcards-validate.mjs"><code>lcards-validate.mjs</code></a> and run <code>node lcards-validate.mjs my-dashboard.yaml</code> (Node.js 20 or newer). <code>--json</code> gives machine-readable output, <code>--strict</code> makes warnings fail too, and <code>-</code> reads the YAML from standard input. It also reads Home Assistant&#39;s <code>.storage/lovelace*</code> files.</li><li><strong>In Home Assistant:</strong> each LCARdS card editor shows schema problems at the top as you edit, and its <strong>YAML</strong> tab checks against the full schema, with lookups, as you type.</li></ul>',12))])}const b=d(u,[["render",g]]);export{A as __pageData,b as default};
